#include "exotic/cognition/storage_schema.hpp"
#include <sqlite3.h>
#include <cassert>
#include <cstdio>
using namespace exotic::cognition;
int main(){const char*p="storage_schema_test.db";std::remove(p);sqlite3*d=nullptr;const int open_rc=sqlite3_open(p,&d);assert(open_rc==SQLITE_OK);if(open_rc!=SQLITE_OK||!d)return 1;apply_storage_migrations(d);assert(storage_schema_version(d)==kCurrentSchemaVersion);sqlite3_stmt*s=nullptr;const int prep1=sqlite3_prepare_v2(d,"SELECT COUNT(*) FROM schema_migrations",-1,&s,nullptr);assert(prep1==SQLITE_OK);if(prep1!=SQLITE_OK){sqlite3_close(d);return 2;}const int step1=sqlite3_step(s);assert(step1==SQLITE_ROW);if(step1!=SQLITE_ROW){sqlite3_finalize(s);sqlite3_close(d);return 3;}assert(sqlite3_column_int(s,0)==kCurrentSchemaVersion);sqlite3_finalize(s);apply_storage_migrations(d);assert(storage_schema_version(d)==kCurrentSchemaVersion);const int prep2=sqlite3_prepare_v2(d,"SELECT name FROM sqlite_master WHERE type='table' AND name IN ('attention_state','belief_revision_history','adaptation_history','intentions')",-1,&s,nullptr);assert(prep2==SQLITE_OK);if(prep2!=SQLITE_OK){sqlite3_close(d);return 4;}int count=0;while(sqlite3_step(s)==SQLITE_ROW)++count;assert(count==4);sqlite3_finalize(s);sqlite3_close(d);std::remove(p);std::remove("storage_schema_test.db-wal");std::remove("storage_schema_test.db-shm");return count==4?0:5;}
